(function(G){
'use strict';
const A=G.BPAnalytics,E=G.BPEngine,M=G.BP_MODEL;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=n=>n==null?'—':(n*100).toFixed(1)+'%';
function portrait(h){return `<img src="${esc(h.image)}" alt="${esc(h.name)}" loading="lazy">`;}
function sideTeam(s,c){return (E.keyOf(s,c)==='A'?s.teamA:s.teamB).name;}
function prediction(s,D){
 const p=A.predict(s,D);
 if(p.unavailable)return `<section class="panel prediction-panel"><div class="panel-head"><h2>本局BP胜率参考</h2><span class="chip gold">暂停</span></div><div class="panel-body help-copy">${esc(p.reason)}</div></section>`;
 const v=M.validation.stages['20'],gap=(p.blue-p.baseline)*100,prior=p.coverage.some(c=>c.unseen||c.sparse);
 const trajectory=[A.predict({...s,actions:[]},D).blue,...s.actions.map((_,i)=>A.predict({...s,actions:s.actions.slice(0,i+1)},D).blue)].filter(Number.isFinite);
 const curve=trajectory.map((v,i)=>`${10+i/20*580},${90-v*70}`).join(' ');
 const rawgroups={side:'蓝方偏置',team:'队伍实力差',pick:'已选英雄残差',ban:'禁用模式',relation:'完整体系 / 对抗',strength:'职业需求先验',structure:'先手 / 前排先验'};
 const support=p.coverage.map(c=>`<div><strong class="${c.camp===1?'strong-blue':'strong-red'}">${esc(sideTeam(s,c.camp))}</strong><span>${c.unseen}名零样本 · ${c.sparse}名不足6局</span></div>`).join('');
 const evidence=p.coverage.map(c=>`<div class="strength-side"><h3 class="${c.camp===1?'strong-blue':'strong-red'}">${esc(sideTeam(s,c.camp))}</h3>${c.heroes.map(h=>`<div class="strength-hero"><button data-detail="${h.id}">${esc(h.name)}</button><span>${h.picks?`${h.picks}选 / ${h.wins}胜`:'零职业出场'} · ${h.bans}Ban</span><span class="${h.picks<6?'strength-low':''}">${h.picks===0?'外推':h.picks<6?'小样本':'有出场证据'}</span></div>`).join('')||'<p class="legal-note">尚未选人</p>'}</div>`).join('');
 return `<section class="panel prediction-panel"><div class="panel-head"><div><span class="eyebrow">BP PROBABILITY / EVIDENCE FIRST</span><h2>本局BP胜率参考</h2></div><span class="chip gold">${p.unsupported?'样本外阵容 · 暂停单点胜率':'实验模型 · 非赛中遥测'}</span></div><div class="panel-body">
 <div class="prob-teams"><div class="strong-blue"><span>${esc(sideTeam(s,1))}</span><strong data-testid="blue-probability">${p.unsupported?'—':pct(p.blue)}</strong></div><div class="prob-center">已选 ${p.picks}/10<small>${p.unsupported?'证据不足，查看先验参考':'随每手BP重算'}</small></div><div class="strong-red"><span>${esc(sideTeam(s,2))}</span><strong data-testid="red-probability">${p.unsupported?'—':pct(p.red)}</strong></div></div>
 ${p.unsupported?'<p class="strength-warning" data-testid="prediction-support-warning">当前包含训练中从未出场的英雄。旧模型会把这些英雄的选人系数设为0，再由队伍实力主导；这里暂停展示单点比赛胜率，避免把未知阵容误判为优势。</p>':`<div class="prob-bar" aria-label="蓝方统计模型参考 ${pct(p.blue)}"><span style="width:${p.blue*100}%"></span></div>`}
 <div class="prob-baseline"><span>队伍基线：蓝方 ${pct(p.baseline)}</span><span>原统计模型对照：蓝方 ${pct(p.blue)}${p.unsupported?'（样本外，不作结论）':` · 相对基线 ${gap>=0?'+':''}${gap.toFixed(1)}pp`}</span></div>
 ${p.unsupported?'':`<svg class="prob-curve" viewBox="0 0 600 100" role="img" aria-label="统计模型BP预测变化曲线"><line x1="10" y1="55" x2="590" y2="55" stroke="#354454" stroke-dasharray="4 5"/><polyline points="${curve}" fill="none" stroke="#9be2c7" stroke-width="2"/></svg>`}<div class="strength-support">${support}</div>
 <details class="strength-experiment" ${prior?'open':''}><summary>英雄强度与结构先验 · 实验参考</summary><div class="strength-prior-probs"><div class="strong-blue"><span>蓝方先验估计</span><strong data-testid="prior-blue-probability">${pct(p.priorBlue)}</strong></div><div><span>蓝方权重敏感范围</span><strong class="strength-range">${pct(p.sensitivity[0])}—${pct(p.sensitivity[1])}</strong></div><div class="strong-red"><span>红方先验估计</span><strong data-testid="prior-red-probability">${pct(p.priorRed)}</strong></div></div>
 <p class="help-copy">把职业选用需求、分路竞争、先手与前排覆盖纳入显式教练先验。低需求会降低职业适配参考；零出场仍不等于0%胜率，单场全胜也不等于100%强度。上方范围来自先验项权重0.5—1.5倍的变化，<strong>不是置信区间，也不是已校准比赛胜率</strong>。</p>
 <div class="strength-evidence">${evidence}</div><p class="legal-note">以上计数为当前概率训练集（${p.n}局），排除顺序异常局；可能与职业数据页144局官方汇总差1局。历史模式使用当时赛前样本。前排与先手来自规则画像，非官方量化能力；类型模板不能表达所有英雄细节。</p>
 <div class="contribution-grid">${Object.entries(p.priorGroups).map(([k,z])=>`<div><span>${rawgroups[k]}</span><strong>${z>=0?'+':''}${z.toFixed(3)}</strong></div>`).join('')}</div>
 <p class="strength-warning">准确性验收未通过：43局留出中，全局启用强度先验的Brier为 ${v.strengthExperiment.brier.toFixed(4)}，原统计模型 ${v.draft.brier.toFixed(4)}，队伍基线 ${v.baseline.brier.toFixed(4)}（越低越好）。先验实验暂不替代统计模型，不能宣称预测更准。</p></details>
 <p class="legal-note">${p.asOf?'赛前口径：仅训练于该系列赛开始前已结束的比赛。':'模拟口径：当前快照，比赛截至10月18日。'}训练 ${p.n}局 / ${p.series}个系列赛${p.through?'，截至 '+esc(p.through.slice(0,10)):''}。${p.n<40?'训练样本极少，主要是先验。':''}未建模选手个人实力和全局英雄池对胜率的影响，比赛服补丁未核验。</p>
 <details class="model-details"><summary>统计模型验证、计算方法与参数</summary><p class="help-copy">按整系列赛和时间隔离，前100局训练、后43局留出。统计模型准确率 ${pct(v.draft.accuracy)}，Brier ${v.draft.brier.toFixed(4)}；仍未超过队伍基线。当前验收集已用于比较多个方案，需要未来独立比赛继续验证。</p><p class="legal-note">需求 = (Pick + 0.5 Ban)/(局初可用机会 + 12)，机会排除该队全局已用英雄族；按主分路至少3次出场英雄需求中位数归一。它不是每手可选条件下的因果强度。每个训练前缀只用此前已结束系列赛的需求，留出期冻结画像。先验系数中心：职业需求1.0、先手0.35、前排0.25；L2回归更新。各项为log-odds，不能直接相加为胜率百分点。未调用赛中经济、人头、伤害。</p><button data-action="model-export" class="ghost tiny">下载模型、画像与验证数据 ↓</button></details>
 </div></section>`;
}
function miniEvidence(e,D,extra=''){
 const H=E.index(D),label=e.ids.map(id=>H[id].name).join(e.type==='ally'?' + ':' 对 ');
 return `<div class="evidence-mini"><div class="evidence-portraits">${e.ids.map(id=>portrait(H[id])).join('')}</div><div><strong>${esc(label)}</strong><p>${e.n}局 · ${e.w}胜 · ${e.teams}队${e.type==='ally'&&e.adjustedLift?' · 队伍分层共现 '+e.adjustedLift.toFixed(1)+'倍':''}</p>${extra}</div><button data-evidence="${e.type}:${e.ids.join(',')}" class="ghost tiny">证据 ↗</button></div>`;
}
function active(s,D){
 if(E.isPeak(s)&&E.turn(s,D))return '';
 const H=E.index(D),hits=[];
 for(const c of [1,2]){const ps=E.picks(s,c,H);for(let i=0;i<ps.length;i++)for(let j=i+1;j<ps.length;j++){const e=A.evidence([ps[i].id,ps[j].id],'ally',s,D);if(e.n>=3&&e.adjustedLift>1.5)hits.push({...e,camp:c});}}
 for(const r of M.relations.filter(r=>r.type==='enemy'))for(const c of [1,2])if(E.picks(s,c,H).some(h=>h.id===r.ids[0])&&E.picks(s,3-c,H).some(h=>h.id===r.ids[1]))hits.push({...A.evidence(r.ids,'enemy',s,D),camp:c});
 return `<section class="panel"><div class="panel-head"><h2>当前阵容 · 比赛关系证据</h2><button class="ghost tiny" data-nav="research">年总拆解 ↗</button></div><div class="panel-body">${hits.slice(0,6).map(e=>miniEvidence(e,D,`<span class="tiny muted">${esc(sideTeam(s,e.camp))} · ${e.type==='ally'?'搭配频率，非胜率加成':'对抗记录，非单挑或因果克制'}</span>`)).join('')||'<p class="help-copy">尚未组成达到样本阈值的关系。补齐英雄后自动检查；未出现的组合不生成伪造优势。</p>'}</div></section>`;
}
const coaching=[
 {title:'钟馗 × 小乔：首轮成套的抓单控制链',text:'钩中目标后接小乔击飞与爆发，是机制上可解释的抓单思路；需要视野与命中率，兵线、挡钩前排和反手保护会影响兑现。该解释是教练假设。',conclusion:'共现支持搭配习惯；44.4%的原始胜率不支持“拿到就优势”。'},
 {title:'狄仁杰 × 元辅 × 嬴政：保留为待验证思路',text:'按用户提出的长手压制与消耗思路观察三人完整组合，并分别统计狄仁杰与元辅二人组。长手阵容还需核查开团、前排、转线和被强开后的处理。',conclusion:'完整三人组零样本，不能从二人共现外推三人体系强度。'},
 {title:'钟无艳 对 镜：后手功能位的候选',text:'石化与近身控制在机制上可能限制镜进场输出，但控制触发、入场时机和队友跟进决定收益。三次跨阵容胜负不能证明英雄克制。',conclusion:'观察到3次均在镜之后的第二阶段选择；样本仅3局。'},
 {title:'项羽 对 关羽：前排控制与冲锋打断',text:'推退与控制在机制上可干扰关羽冲锋、隔开进场路径，适合检查阵容是否需要限制绕后。边线优先权和团队控制分工仍要看完整五人。',conclusion:'13次同局对抗、12次后手选择，支持“针对性选择习惯”，不等于必胜克制。'}
];
function examples(e,D){return e.examples.slice(0,3).map(x=>{const g=D.games.find(g=>g.id===x.id);return `<div class="research-case"><div><strong>${esc(g.blue.name)} vs ${esc(g.red.name)}</strong><p>${g.date.slice(5,16)} · 第${g.seq}局 · ${esc(e.ids.map(id=>D.heroes.find(h=>h.id===id).name).join(' / '))}</p><div class="case-picks">${g.actions.map((a,i)=>({...a,i})).filter(a=>a.type==='pick'&&e.ids.includes(a.hero)).map(a=>`<span class="${a.camp===1?'strong-blue':'strong-red'}">${a.i+1}手 ${esc(D.heroes.find(h=>h.id===a.hero).name)}</span>`).join(' → ')}</div></div><div class="inline-buttons">${g.replayable?`<button data-replay="${g.id}" class="tiny">回放BP</button>`:''}<a href="${esc(g.video)}" target="_blank" rel="noopener" class="tiny">录像 ↗</a><a href="${esc(g.source)}" target="_blank" rel="noopener" class="tiny">原始数据 ↗</a></div></div>`;}).join('')||'<p class="legal-note">当前窗口暂无完整样本，不补造案例。</p>';}
function research(s,D){
 const all={...s,analysisMatchId:undefined},H=E.index(D),v=M.validation,R=G.BP_RESEARCH;
 const cards=M.relations.map((r,i)=>{const e=A.evidence(r.ids,r.type,all,D),c=coaching[i],raw=R.hypotheses[i];
  const extra=r.type==='ally'?`首轮集齐 ${e.phase1}/${e.ordered} 次${i===0&&s.window==='all'?'；同轮双选15次，小乔较早轮10次，钟馗较早轮2次':''}`:`其后选出 ${e.after}/${e.ordered} 次`;
  const opportunity=raw?.opportunities;
  return `<article class="panel research-card"><div class="panel-head"><h2>${c.title}</h2><span class="chip ${e.n<8?'gold':'mint'}">${e.n===0?'待验证':e.n<8?'小样本':'有共现证据'}</span></div><div class="panel-body"><div class="research-heroes">${r.ids.map(id=>`<button data-detail="${id}">${portrait(H[id])}<span>${esc(H[id].name)}</span></button>`).join('')}</div><div class="evidence-stats"><div><strong>${e.n}</strong><span>完整关系样本</span></div><div><strong>${e.w} / ${e.n-e.w}</strong><span>胜 / 负</span></div><div><strong>${pct(e.rate)}</strong><span>原始胜率</span></div><div><strong>${e.teams}</strong><span>采用队伍数</span></div></div><p class="tiny muted">${extra}。${e.interval?'胜率95% Wilson区间 '+pct(e.interval[0])+'—'+pct(e.interval[1])+'；':'无胜率区间；'}${e.adjustedLift?'队伍分层共现 '+e.adjustedLift.toFixed(2)+'倍。':''}</p><p class="help-copy" style="margin-top:12px">${c.text}</p><div class="research-conclusion">${s.window==='all'?c.conclusion:'近期窗口重新计数；全赛事解读请切换“年总全部”。'}</div>${i===1?miniEvidence(A.evidence([133,585],'ally',all,D),D):''}${s.window==='all'&&opportunity?`<div class="opportunity-box"><strong>目标亮出后、仍可响应的选择率</strong><p>面对${esc(H[r.ids[1]].name)}：${opportunity.target.picks}/${opportunity.target.n}（${pct(opportunity.target.rate)}）<br>面对其他${esc(opportunity.targetRole)}：${opportunity.other.picks}/${opportunity.other.n}（${pct(opportunity.other.rate)}）</p><details><summary>条件分母如何计算</summary><p class="legal-note">${esc(opportunity.method)}</p><p class="legal-note">控制既有Ban、全局已用与占位；实际分路来自赛后记录，摇摆位仍不确定。选择行为不能证明因果克制。</p></details></div>`:''}<details><summary>查看真实BP案例与时序</summary>${examples(e,D)}</details></div></article>`;}).join('');
 const pairs=A.topPairs(all,D).slice(0,8);
 return `<div class="page-title"><div><div class="eyebrow">ANNUAL FINALS / MATCH-BASED BP RESEARCH</div><h1>从选择顺序，拆解体系。</h1><p>2026年总 · ${s.window==='all'?'10月2日—18日全部144局':'10月15日起日期窗口'} · 统计证据与教练机制解释分开展示</p></div><div class="page-number">07</div></div><div class="versions-box">当前快照截至10月18日，赛事服补丁未核验。共现不等于配合增益；完整阵容胜率不等于单英雄克制。统计不包含经济、人头与团战事件，不能据此还原选手执行过程或认定教练意图。</div><div class="research-grid">${cards}</div><section class="panel section-gap"><div class="panel-head"><h2>从年总发现的高频搭配</h2><span class="chip">至少4局 · 至少2队</span></div><div class="panel-body">${pairs.map(e=>miniEvidence(e,D)).join('')||'<p class="legal-note">当前窗口暂无符合阈值的组合。</p>'}<p class="legal-note">按共现次数排序；分层倍数 = 实际共现 / 按各队自身英雄使用率计算的独立共现期望。它控制队伍搭配习惯，但未控制分路竞争、系列赛英雄消耗与选手。推荐关系项改为该样本统计；小样本按 n/(n+12) 收缩。对抗项使用相对该场赛前队伍基线的胜负残差，指定反制另参考条件响应选择率差；最多±8分，不视为因果效应。</p></div></section><section class="panel section-gap"><div class="panel-head"><h2>年总BP思路 · 如何用证据落到下一手</h2></div><div class="panel-body research-notes"><p><strong>首轮看成套，避免只抢单卡。</strong>钟馗小乔26/27次、盾山艾琳28/28次在首轮集齐。保住第二张搭配卡与破解对方体系，应一起比较；同方连续双选算同一轮，不能把接口内部顺序解释为先后决策。</p><p><strong>后手看任务，先确认目标已暴露。</strong>项羽对关羽多在首轮回应；钟无艳对镜的3次出场都在第二阶段。Ban与Pick必须先过滤已占位置和全局已用英雄，再比较功能，不因名称标签制造非主流摇摆。</p><p><strong>系列赛看机会成本。</strong>先检查当前局次的可用池，再判断是否拆掉后续成套组合。当前仍是有限分支搜索，尚未求解整场系列赛胜率。</p><p><strong>把机制假设交给录像核验。</strong>案例可打开官方记录、录像和BP回放；钩中跟控、打断冲锋、前排交换、边线转线等细节需要逐段录像标注，当前接口没有这些事件。</p></div></section><section class="panel section-gap"><div class="panel-head"><h2>胜率模型 · 独立留出验证</h2><button class="ghost tiny" data-action="model-export">下载模型与验证数据 ↓</button></div><div class="panel-body"><p class="help-copy">${esc(M.method)} ${esc(v.method)}</p><p class="legal-note">训练 ${v.trainGames}局 / ${v.trainSeries}个系列赛；留出 ${v.testGames}局 / ${v.testSeries}个系列赛；分界 ${v.cutoff}。每局按原始10月日期整体归组，21个BP前缀合计权重1，不把前缀冒充独立比赛。</p><div class="data-table-wrap"><table class="data-table"><thead><tr><th>BP节点</th><th>阵容模型准确率</th><th>Brier（越低越好）</th><th>队伍基线 Brier</th><th>Log loss</th></tr></thead><tbody>${Object.entries(v.stages).map(([n,r])=>`<tr><td>${n==='0'?'BP开始':n==='10'?'首轮结束 / 6选':'完整BP'}</td><td>${pct(r.draft.accuracy)}</td><td>${r.draft.brier.toFixed(4)}</td><td>${r.baseline.brier.toFixed(4)}</td><td>${r.draft.logLoss.toFixed(4)}</td></tr>`).join('')}</tbody></table></div><div class="research-conclusion">本次留出中，阵容模型尚未超过队伍基线。功能可用于观察预测随BP变化，暂不能宣称已验证阵容带来更准确的预测。</div><p class="legal-note">正式模拟模型使用143局；排除1局原始BP顺序异常。历史回放/接管保留赛前模型：训练集合中没有该系列赛及之后的比赛。关系证据在历史模拟中也按赛前日期截断；基础热度和规则能力仍使用当前快照，所以推荐不作为无未来信息回测。预测不读取赛果以外的赛后统计，也没有接入比赛中的实时遥测。未单独建模选手或比赛服补丁。</p></div></section>`;
}
function relationship(s,D,ids,type){const e=A.evidence(ids,type,s,D),H=E.index(D);return {title:ids.map(id=>H[id].name).join(type==='ally'?' + ':' 对 '),body:`${miniEvidence(e,D)}<p class="help-copy">${e.n}局 / ${e.w}胜，原始胜率 ${pct(e.rate)}。${e.interval?'95% Wilson区间 '+pct(e.interval[0])+'—'+pct(e.interval[1])+'。':''}样本来自完整阵容比赛，不代表两英雄的独立增益或因果克制。</p>${examples(e,D)}<p class="legal-note">当前${s.analysisMatchId?'赛前截断':s.window==='recent'?'近期':'全赛事'}样本；最多显示3个案例。</p>`};}
G.BPInsightUI={prediction,active,research,relationship};
})(globalThis);
